contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _keepAddress) public payable {
        bool approvedBefore = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;
        bool returned = c.logCreated(_keepAddress); if (__ESBMC_reverted()) return;
        bool approvedAfter = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;
        assert(returned == approvedBefore && approvedAfter == approvedBefore);
    }

    receive() external payable {}
}

