pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(address _keepAddress) internal {
        bool approvedBefore;
        try c.approvedToLog(address(this)) returns (bool __r) { approvedBefore = __r; } catch { return; }
        bool returned;
        try c.logCreated(_keepAddress) returns (bool __r) { returned = __r; } catch { return; }
        bool approvedAfter;
        try c.approvedToLog(address(this)) returns (bool __r) { approvedAfter = __r; } catch { return; }
        assertTrue(returned == approvedBefore && approvedAfter == approvedBefore);
    }

    function testFuzz_run(address _keepAddress) public {
        vm.assume(_keepAddress.code.length == 0 && uint160(_keepAddress) > 0xffff && _keepAddress != address(this) && _keepAddress != address(c) && _keepAddress != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _keepAddress != 0x000000000000000000636F6e736F6c652e6c6f67 && _keepAddress != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _keepAddress != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_keepAddress);
    }

    receive() external payable {}
}
